import{_ as a,o as t,c as o,a0 as n}from"./chunks/framework.akKRIpjQ.js";const u=JSON.parse('{"title":"10 · FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/10-faq.md","filePath":"guide/10-faq.md"}'),i={name:"guide/10-faq.md"};function r(l,e,s,h,c,d){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_10-·-faq" tabindex="-1">10 · FAQ <a class="header-anchor" href="#_10-·-faq" aria-label="Permalink to &quot;10 · FAQ&quot;">​</a></h1><h3 id="_1-is-the-app-completely-free" tabindex="-1">1. Is the App completely free? <a class="header-anchor" href="#_1-is-the-app-completely-free" aria-label="Permalink to &quot;1. Is the App completely free?&quot;">​</a></h3><p><strong>Yes</strong>. No ads, no IAP, no premium tier.</p><h3 id="_2-will-v1-1-cost-money" tabindex="-1">2. Will V1.1 cost money? <a class="header-anchor" href="#_2-will-v1-1-cost-money" aria-label="Permalink to &quot;2. Will V1.1 cost money?&quot;">​</a></h3><p><strong>No</strong>.</p><h3 id="_3-is-my-data-uploaded" tabindex="-1">3. Is my data uploaded? <a class="header-anchor" href="#_3-is-my-data-uploaded" aria-label="Permalink to &quot;3. Is my data uploaded?&quot;">​</a></h3><p><strong>No</strong>, unless you tap <a href="./09-feedback.html">Feedback</a>.</p><h3 id="_4-after-uninstall-can-i-recover-data" tabindex="-1">4. After uninstall, can I recover data? <a class="header-anchor" href="#_4-after-uninstall-can-i-recover-data" aria-label="Permalink to &quot;4. After uninstall, can I recover data?&quot;">​</a></h3><p>If you haven&#39;t set up cloud sync — yes, it&#39;s gone. Use JSON export regularly as a manual backup (<a href="./07-settings.html#data-management">07 · Settings → Data management</a>). If you have set up cloud sync (<a href="./06-cloud-sync.html">06 · Cloud Sync</a>), sign in on the new device with the same account and pull everything back.</p><h3 id="_5-when-is-ios-coming" tabindex="-1">5. When is iOS coming? <a class="header-anchor" href="#_5-when-is-ios-coming" aria-label="Permalink to &quot;5. When is iOS coming?&quot;">​</a></h3><p>No available build yet. See <a href="./00-introduction.html#supported-platforms">00 · Supported platforms</a>.</p><h3 id="_6-app-launches-blank-hangs-—-what-now" tabindex="-1">6. App launches blank / hangs — what now? <a class="header-anchor" href="#_6-app-launches-blank-hangs-—-what-now" aria-label="Permalink to &quot;6. App launches blank / hangs — what now?&quot;">​</a></h3><ol><li>Relaunch</li><li>Still broken? <code>Me → Data → Delete all data</code> (export JSON first)</li><li>Still broken? Uninstall + reinstall</li></ol><h3 id="_7-how-do-i-put-the-icon-on-the-home-screen" tabindex="-1">7. How do I put the icon on the home screen? <a class="header-anchor" href="#_7-how-do-i-put-the-icon-on-the-home-screen" aria-label="Permalink to &quot;7. How do I put the icon on the home screen?&quot;">​</a></h3><p>Android places the icon at install. Long-press to drop into a folder if you&#39;d like.</p><h3 id="_8-i-use-a-third-party-launcher-e-g-nova-and-the-icon-looks-different" tabindex="-1">8. I use a third-party launcher (e.g. Nova) and the icon looks different? <a class="header-anchor" href="#_8-i-use-a-third-party-launcher-e-g-nova-and-the-icon-looks-different" aria-label="Permalink to &quot;8. I use a third-party launcher (e.g. Nova) and the icon looks different?&quot;">​</a></h3><p>Adaptive icons render differently across launchers; behavior is unaffected.</p><h3 id="_9-can-i-export-as-pdf-excel" tabindex="-1">9. Can I export as PDF / Excel? <a class="header-anchor" href="#_9-can-i-export-as-pdf-excel" aria-label="Permalink to &quot;9. Can I export as PDF / Excel?&quot;">​</a></h3><p>V1.0 is JSON only. V1.1+ adds CSV (opens in Excel).</p><h3 id="_10-can-i-contribute-a-translation" tabindex="-1">10. Can I contribute a translation? <a class="header-anchor" href="#_10-can-i-contribute-a-translation" aria-label="Permalink to &quot;10. Can I contribute a translation?&quot;">​</a></h3><p>Not open yet. V1.0 ships in 简体中文 + English.</p><h3 id="_11-will-this-project-go-open-source" tabindex="-1">11. Will this project go open-source? <a class="header-anchor" href="#_11-will-this-project-go-open-source" aria-label="Permalink to &quot;11. Will this project go open-source?&quot;">​</a></h3><p><a href="./00-introduction.html#what-v10-is-not-doing">A decision will be made after the V1.0 store launch</a>. Source code and build scripts are not currently provided.</p><h3 id="_12-i-hit-a-bug-in-testing-—-how-to-report" tabindex="-1">12. I hit a Bug in testing — how to report? <a class="header-anchor" href="#_12-i-hit-a-bug-in-testing-—-how-to-report" aria-label="Permalink to &quot;12. I hit a Bug in testing — how to report?&quot;">​</a></h3><p><strong>Fastest</strong>: in-App <code>Me → Send feedback</code> (see <a href="./09-feedback.html">09 · Feedback</a>). <strong>Email</strong>: <a href="mailto:acecrushdev@gmail.com" target="_blank" rel="noreferrer">acecrushdev@gmail.com</a> (attach screenshots).</p><h3 id="_13-will-ios-safari-deep-link-to-the-app-work" tabindex="-1">13. Will iOS Safari deep-link to the App work? <a class="header-anchor" href="#_13-will-ios-safari-deep-link-to-the-app-work" aria-label="Permalink to &quot;13. Will iOS Safari deep-link to the App work?&quot;">​</a></h3><p><strong>It won&#39;t</strong>, because there&#39;s no iOS build and Universal Links aren&#39;t configured. Open the official site instead.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./06-cloud-sync.html">06 · Cloud Sync</a></li><li><a href="./07-settings.html">07 · Settings</a></li><li><a href="./08-privacy.html">08 · Privacy</a></li><li><a href="./09-feedback.html">09 · Feedback</a></li></ul>',29)])])}const f=a(i,[["render",r]]);export{u as __pageData,f as default};
